#include "runtime/interpreter.hpp"
#include "native_functions/native_callback.hpp"
#include "native_functions/third_callback.hpp"
#include <nlohmann/json.hpp>
#include <chrono>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <future>
#include <iostream>
namespace {
using namespace penta;int checks=0,failures=0;
void expect(bool okay,const char* message){++checks;if(!okay){++failures;std::cerr<<"FAIL: "<<message<<'\n';}}
void show(const runtime::ExecutionResult& result){for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<" @"<<d.span.offset<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<" @"<<d.span.offset<<": "<<d.message<<'\n';}
auto function(const std::string& source){const auto result=language::analyse(source);if(!result.ok()){for(const auto& d:result.diagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';throw std::runtime_error("Tensor callback failed static checking.");}for(const auto& statement:result.program.statements)if(statement.function)return statement.function;throw std::runtime_error("Missing tensor fixture callback.");}
void nativeCases(const std::filesystem::path& directory){
    native_functions::Options options;options.build.cacheDirectory=directory/"callbacks";
    const auto f=function("native function tensor<2,2,2> cubes(tensor<2,2,2> x){return x.*x.*x;}");
    native_functions::Callback callback(*f,options);native_functions::DerivativeRequest request;request.order=1;const auto output=callback.evaluate(1,{1,2,3,4,5,6,7,8},request);
    expect(output.values==std::vector<double>({1,8,27,64,125,216,343,512}),"Compiled rank-three callbacks retain all column-major entries.");
    bool correct=output.jacobian.size()==64;for(unsigned i=0;i<8;++i)for(unsigned j=0;j<8;++j)correct=correct&&output.jacobian[8*i+j]==(i==j?3.*(i+1)*(i+1):0);expect(correct,"Tensor AD1 agrees with eight independent cubic derivatives.");
    request.order=2;request.direction.assign(8,1);const auto second=callback.evaluate(1,{1,2,3,4,5,6,7,8},request);correct=second.second.size()==64;for(unsigned i=0;i<8;++i)for(unsigned j=0;j<8;++j)correct=correct&&second.second[8*i+j]==(i==j?6.*(i+1):0);expect(correct,"Tensor AD2 retains the full output-major Hessian-direction layout.");
    native_functions::ThirdCallback third(*f,options);native_functions::ThirdRequest directions;directions.u=directions.v=directions.w=std::vector<double>(8,1);expect(third.evaluate(1,{1,2,3,4,5,6,7,8},directions).third==std::vector<double>(8,6),"Tensor AD3 independently differentiates every cubic entry.");
    native_functions::Callback reused(*f,options);expect(reused.cacheHit()&&reused.key()==callback.key(),"Unchanged tensor bodies reuse their cached shared object.");
    auto concurrent=[&]{native_functions::DerivativeRequest r;r.order=0;return callback.evaluate(1,{2,2,2,2,2,2,2,2},r).values;};auto a=std::async(std::launch::async,concurrent),b=std::async(std::launch::async,concurrent);expect(a.get()==std::vector<double>(8,8)&&b.get()==std::vector<double>(8,8),"Tensor callback buffers remain reentrant across concurrent native calls.");
    const auto other=function("native function tensor<4,2> cubes(tensor<4,2> x){return x.*x.*x;}");expect(native_functions::callbackFingerprint(*other)!=native_functions::callbackFingerprint(*f),"Same-width tensors with distinct ranks/shapes have different structural cache identities.");
    const auto indexed=function("native function real selected(tensor<2,2,2> x){return x(2,1,2);}");native_functions::Callback select(*indexed,options);native_functions::DerivativeRequest first;first.order=1;const auto chosen=select.evaluate(1,{1,2,3,4,5,6,7,8},first);expect(chosen.values==std::vector<double>{6}&&chosen.jacobian==std::vector<double>({0,0,0,0,0,1,0,0}),"Native tensor indexing uses every declared axis in the column-major ABI.");
    const std::string algebras="algebra A=builtin_algebra(\"complex\");algebra B=builtin_algebra(\"split_complex\");";
    const auto firstBinding=function(algebras+"native function real same_name(tensor<A,1> x,tensor<B,1> y){tensor<1> selected=coeff(x.*x,0);return selected(1);}");
    const auto secondBinding=function(algebras+"native function real same_name(tensor<B,1> x,tensor<A,1> y){tensor<1> selected=coeff(x.*x,0);return selected(1);}");
    expect(native_functions::callbackFingerprint(*firstBinding)!=native_functions::callbackFingerprint(*secondBinding),"Tensor fingerprints bind each parameter to its own algebra hash, beyond the sorted definition set.");
    native_functions::Callback elliptic(*firstBinding,options),hyperbolic(*secondBinding,options);native_functions::DerivativeRequest plain;plain.order=0;
    expect(elliptic.key()!=hyperbolic.key()&&elliptic.evaluate(1,{0,1,0,0},plain).values==std::vector<double>{-1}&&hyperbolic.evaluate(1,{0,1,0,0},plain).values==std::vector<double>{1},"Equal-width swapped algebra bindings retain distinct compiled identities and opposite quadratic values.");
    bool temporaryRejected=false;try{const auto oversized=function("algebra S=builtin_algebra(\"sedenion\");native function real too_wide(real x){return norm(tensor(x,[128],S));}");(void)native_functions::callbackFingerprint(*oversized);}catch(const ode::OdeError& error){temporaryRejected=error.code=="N2401";}
    expect(temporaryRejected,"An unnamed tensor temporary counts every algebra coefficient against the local allowance.");
    const auto local=function("native function real larger_local(real x){return norm(tensor(x,[256]));}");native_functions::Callback localCallback(*local,options);native_functions::DerivativeRequest derivative;derivative.order=1;const auto localValue=localCallback.evaluate(1,{2},derivative);
    expect(localValue.values==std::vector<double>{32}&&localValue.jacobian==std::vector<double>{16},"A valid256-coordinate local tensor is distinct from the128-coordinate callback boundary.");

}
void languageCases(const std::filesystem::path& directory){
    runtime::ExecutionOptions options;options.dataDirectory=directory;options.odeCacheDirectory=directory/"odes";
    auto run=[&](const std::string& source,bool valid,const char* message){const auto result=runtime::execute(source,{},options);if(valid&&!result.ok())show(result);expect(result.ok()==valid,message);return result;};
    run("tensor<2,2,2> x=tensor([2],[2,2,2]);assert(x(8)==2);assert(sum(x,\"all\")==16);algebra H=builtin_algebra(\"quaternion\");tensor<H,2,1,1> y=tensor([H.i],[2,1,1]);assert(y(2)==H.i);",true,"One-entry real/generic matrices broadcast consistently with native tensor constructors.");
    run("tensor<2,2,2> A=tensor([1,3,5,7;2,4,6,8],[2,2,2]);assert(A(2,1,2)==6);assert(A(8)==8);assert(norm(tensorvalues(A)-[1;2;3;4;5;6;7;8])==0);assert(ndims(A)==3);assert(size(A,3)==2);assert(size(A,4)==1);assert(numel(A)==8);assert(tensorinfo(A).rank==3);",true,"Tensor constructors reorder existing matrix entries without changing the old matrix ABI.");
    run("tensor<2,2,2> A=tensor(1,[2,2,2]);tensor<2,2,2> B=A;A(2,1,2)=7;assert(A(6)==7);assert(B(6)==1);tensor<4,2> C=tensor(A,[4,2]);assert(C(2,2)==7);assert(norm(C,\"fro\")==sqrt(56));",true,"Tensor mutation is copy-on-write and explicit reshape preserves packed entry order.");
    run("tensor<2,2> A=tensor([1,2;3,4],[2,2]);integer first=1;tensor selected=A(first:2,1);assert(numel(selected)==2);assert(selected(1)==1&&selected(2)==3);tensor<2,1> fixed=A(first:2,1);assert(fixed==selected);",true,"Runtime tensor slice extents resolve inferred declarations without relaxing explicit fixed shapes.");
    run("tensor<2,2> A=tensor(1,[2,2]);integer first=2;tensor<2,1> fixed=A(first:2,1);",false,"An explicit tensor shape still rejects a dynamically selected different extent.");
    runtime::InterpreterSession inferred;const auto inferredDeclaration=inferred.submit("tensor<2,2> A=tensor(1,[2,2]);integer first=1;tensor selected=A(first:2,1);",{},options);if(!inferredDeclaration.ok())show(inferredDeclaration);expect(inferredDeclaration.ok(),"A runtime slice resolves its complete inferred tensor descriptor.");const auto changedInferred=inferred.submit("selected=tensor(0,[3]);",{},options);expect(!changedInferred.ok(),"A later command cannot change an inferred runtime tensor shape.");const auto preservedInferred=inferred.submit("assert(size(selected,1)==2&&size(selected,2)==1&&sum(selected)==2);",{},options);if(!preservedInferred.ok())show(preservedInferred);expect(preservedInferred.ok(),"Rejected inferred tensor shape changes preserve its complete original value.");
    run("tensor<2,2> A=tensor(1,[2,2]);A(:,1)=0;assert(A(1,1)==0&&A(2,1)==0&&A(1,2)==1);",true,"Scalar tensor slice assignment broadcasts within its original full shape.");
    run("algebra H=builtin_algebra(\"quaternion\");tensor<H,2,2> A=tensor(H.one,[2,2]);A(:,1)=H.i;assert(A(1,1)==H.i&&A(2,1)==H.i&&A(2,2)==H.one);",true,"Generic tensor slices broadcast only a compatible full algebra entry.");
    run("algebra H=builtin_algebra(\"quaternion\");tensor<H,2,1,1> A=tensor([0,1,0,0;0,0,1,0],[2,1,1],H);tensor<H,2,1,1> R=A*H.i;tensor<H,2,1,1> L=H.i*A;assert(R(1)==-1);assert(R(2)==-H.k);assert(L(2)==H.k);assert(tensorinfo(A).algebra_hash==algebra_info(H).hash);tensor<2,1,1> c=coeff(A,2);assert(c(2)==1);",true,"Generic tensor multiplication retains ordered algebra actions and every basis coefficient.");
    run("algebra L=builtin_algebra(\"lie_so3\");tensor<L,2> zero=tensor(0,[2],L);assert(norm(zero)==0);zero(:)=L.x;zero(:)=0;assert(norm(zero)==0);",true,"An explicit zero tensor preserves every coordinate in a nonunital algebra without inventing a unit.");
    run("algebra L=builtin_algebra(\"lie_so3\");tensor<L,2> invalid=tensor(1,[2],L);",false,"Nonzero tensor scalar embedding still requires a verified algebra unit.");
    run("algebra H=builtin_algebra(\"quaternion\");tensor<H,2> small=tensor(1e-309*H.i,[2]);tensor<H,2> scaled=small/1e-309;assert(scaled(1)==H.i&&scaled(2)==H.i);",true,"Generic tensor real division retains finite complete quotients even when the divisor reciprocal overflows.");
    run("tensor A=tensor(1e308,[2]);assert(mean(A)==1e308);tensor cancelled=tensor([1e308,1e308,-1e308],[3]);assert(sum(cancelled)==1e308);real tiny=4.9406564584124654e-324;tensor small=tensor(tiny,[3]);assert(mean(small)==tiny);",true,"Real tensor reductions use ordered wide sums and preserve large and minimum-subnormal constant means.");
    run("complex z=complex(1e308,-1e308);tensor A=tensor(z,[2]);assert(mean(A)==z);tensor cancelledZ=tensor([1e308,-1e308;1e308,-1e308;-1e308,1e308],[3],\"complex\");assert(sum(cancelledZ)==z);pentarnion p=pent([1e308,1e308,-1e308,1e308,-1e308]);tensor P=tensor(p,[2]);assert(mean(P)==p);tensor cancelled=tensor([p,p,-p],[3]);assert(sum(cancelled)==p);real tiny=4.9406564584124654e-324;complex smallZ=complex(tiny,-tiny);tensor Z=tensor(smallZ,[3]);assert(mean(Z)==smallZ);pentarnion smallP=tiny*(i+ell);tensor Q=tensor(smallP,[3]);assert(mean(Q)==smallP);",true,"Complex and Pentarnion tensor reductions retain every complete entry coefficient and original domain.");
    run("algebra H=builtin_algebra(\"quaternion\");element<H> big=element(H,[1e308,1e308,-1e308,1e308]);tensor A=tensor(big,[2]);assert(mean(A)==big);tensor cancelled=tensor([big,big,-big],[3]);assert(sum(cancelled)==big);real tiny=4.9406564584124654e-324;element<H> small=tiny*H.i;tensor retained=tensor(small,[3]);assert(mean(retained)==small);",true,"Generic tensor reductions retain immutable algebra, full coordinates and minimum-subnormal constant means.");
    run("tensor<complex,2,1,1> z=tensor([1,2;3,4],[2,1,1],\"complex\");assert(z(2)==complex(3,4));tensor<complex,2,1,1> w=z.*conj(z);assert(w(1)==complex(5,0));assert(w(2)==complex(25,0));assert(abs(norm(z)-sqrt(30))<1e-12);",true,"Complex tensor entries are explicitly distinct from generic algebra and real data.");
    run("tensor<pentarnion,2,1,1> A=tensor(1+i+ell,[2,1,1]);assert(coeff(A(2),4)==1);tensor<pentarnion,2,1,1> B=exp(A);assert(norm(B-tensor(exp(1+i+ell),[2,1,1]))<1e-12);",true,"Legacy Pentarnion tensor entries retain the complete whole-element calculus.");
    run("algebra S=builtin_algebra(\"sedenion\");tensor<S,2,1,1> A=tensor(S.e15,[2,1,1]);assert(coeff(A(2),15)==1);assert(size(tensorvalues(A),2)==16);save(\"tensors.pws\",\"A\");",true,"Sedenion tensor serialization preserves all sixteen coefficients and frozen identity.");
    run("algebra H=builtin_algebra(\"quaternion\");matrix<H,1,2> retained=[H.i,H.j];save(\"generic-matrix.pws\",\"retained\");",true,"Generic matrices retain complete algebra descriptors in saved data.");
    runtime::InterpreterSession matrixRestore;const auto restoredMatrix=matrixRestore.submit("load(\"generic-matrix.pws\");",{},options);if(!restoredMatrix.ok())show(restoredMatrix);expect(restoredMatrix.ok(),"Generic matrix snapshot loads before a later checked submission.");const auto usedMatrix=matrixRestore.submit("assert(coeff(retained,1)(1,1)==1);assert(coeff(retained,2)(1,2)==1);",{},options);if(!usedMatrix.ok())show(usedMatrix);expect(usedMatrix.ok(),"Generic matrix workspace symbols remain supported across command boundaries.");
    runtime::InterpreterSession restored;const auto load=restored.submit("load(\"tensors.pws\");",{},options);if(!load.ok())show(load);expect(load.ok(),"Tensor workspace restoration checks its exact full coefficient schema.");const auto replay=restored.submit("assert(tensorinfo(A).components==16);assert(coeff(A(2),15)==1);",{},options);if(!replay.ok())show(replay);expect(replay.ok(),"Restored tensors retain generic entry typing in subsequent checked submissions.");
    run("tensor<2,2,2> A=tensor(1,[2,2,2]);tensor<4,2> B=tensor(1,[4,2]);A=B;",false,"Equal coordinate counts cannot replace a different tensor shape.");
    run("tensor<2,2,2> A=tensor(1,[2,2,2]);tensor B=A*A;",false,"Tensor pair multiplication requires explicit entrywise semantics.");
    run("tensor<2,2,2> A=tensor(1,[2,2,2]);real x=A(2,3,1);",false,"Each tensor selector is checked against its own declared extent.");
    run("tensor A=tensor(1,[0,2,3]);",false,"Native tensor shapes require positive extents.");
    auto tiny=options;tiny.maxMatrixCoordinates=7;expect(!runtime::execute("tensor A=tensor(1,[2,2,2]);",{},tiny).ok(),"Host resource limits count every retained tensor coordinate before allocation.");
    const std::string decay="ode decay(t,tensor<2,2,2> x;real rate){x'=-rate*x;}tensor<2,2,2> initial=tensor([1,2,3,4,5,6,7,8],[2,2,2]);solution simulation=odesolve(decay,x=initial,rate=0.5,t0=0,t1=1,sample_step=0.1,rtol=1e-10,atol=1e-12);tensor<2,2,2> final=simulation.x(length(simulation.t));assert(norm(final-exp(-0.5)*initial)<1e-8);tensor<2,2,2> midpoint=deval(simulation,0.5);assert(norm(midpoint-exp(-0.25)*initial)<1e-8);assert(abs(statecoord(simulation.x,7)(length(simulation.t))-8*exp(-0.5))<1e-8);save(\"tensor-state.pws\",\"simulation\",\"final\");";
    run(decay,true,"Native tensor ODE states support analytic Jacobians, dense output and flat coordinate observations.");const auto cached=run(decay,true,"Repeated tensor ODEs preserve native solve behavior.");if(cached.ok())expect(cached.nativeCompilation.compilerAttempts==0,"A cached tensor ODE body is not recompiled for later runs.");
    runtime::InterpreterSession savedState;const auto loaded=savedState.submit("load(\"tensor-state.pws\");",{},options);if(!loaded.ok())show(loaded);expect(loaded.ok(),"Saved tensor solution metadata restores exact rank and entry type.");const auto last=savedState.submit("tensor<2,2,2> last=simulation.x(length(simulation.t));assert(norm(last-final)<1e-12);save(\"tensor-series.pws\",\"last\");",{},options);if(!last.ok())show(last);expect(last.ok(),"Loaded tensor series reconstruct typed tensor samples without width guessing.");
    std::ifstream stream(directory/"tensors.pws");nlohmann::json bad;stream>>bad;bad["variables"]["A"]["shape"]={1,1,1};{std::ofstream output(directory/"bad.pws");output<<bad.dump();}expect(!restored.submit("load(\"bad.pws\");",{},options).ok(),"Corrupted tensor shape metadata rejects atomically rather than discarding coefficients.");
}
}
int main(){const auto directory=std::filesystem::temp_directory_path()/("penta-typed-tensors-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));try{std::filesystem::create_directories(directory);nativeCases(directory);languageCases(directory);}catch(const std::exception& error){++failures;std::cerr<<"Unexpected: "<<error.what()<<'\n';}std::error_code ignored;std::filesystem::remove_all(directory,ignored);std::cout<<checks<<" typed tensor native/language checks, "<<failures<<" failures\n";return failures?1:0;}
